import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"LLM models","description":"","frontmatter":{"title":"LLM models"},"headers":[],"relativePath":"docs/concepts/llm-models.md","filePath":"docs/concepts/llm-models.md","lastUpdated":1790443712000}'),d={name:"docs/concepts/llm-models.md"};function r(n,e,l,i,u,c){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="llm-models" tabindex="-1">LLM models <a class="header-anchor" href="#llm-models" aria-label="Permalink to &quot;LLM models&quot;">​</a></h1><p>Models are what power chat and question-answering in OrbySystems. OrbySystems distinguishes <strong>builtin</strong> models from <strong>configured</strong> models — the choice of which to use is yours, and can be changed at any time in <a href="/docs/settings/models">Settings → Models</a>.</p><h2 id="builtin-models" tabindex="-1">Builtin models <a class="header-anchor" href="#builtin-models" aria-label="Permalink to &quot;Builtin models&quot;">​</a></h2><p>Builtin models are run by OrbySystems itself, entirely on your own machine. Because OrbySystems controls them directly, they&#39;re always local and always trusted — nothing more to decide.</p><h2 id="configured-models" tabindex="-1">Configured models <a class="header-anchor" href="#configured-models" aria-label="Permalink to &quot;Configured models&quot;">​</a></h2><p>You can also configure additional models of your own — a different local model, a cloud API, or a subscription like Codex. Whether a configured model is trusted or untrusted is up to you, and depends on where it&#39;s actually running, who&#39;s running it, and how much you trust that setup. For example, you might configure a Codex subscription as an untrusted model.</p><h2 id="cloud-models" tabindex="-1">Cloud models <a class="header-anchor" href="#cloud-models" aria-label="Permalink to &quot;Cloud models&quot;">​</a></h2><p>A cloud model is a configured model that runs on someone else&#39;s servers — the state-of-the-art models from the leading AI providers. Using one means sending it whatever you&#39;d normally keep local: your questions, and any project data included to answer them.</p><p>That provider&#39;s terms of service govern what they say they&#39;ll do with what you send — but a ToS can change, and by the time it does, your data is already with them. It&#39;s also subject to the same risks as any data held by a third party: a leak or breach, whether from an outside attacker or someone inside the company. Weigh that before sending a cloud model anything you wouldn&#39;t want to leave your machine — see <a href="/docs/privacy-and-security/trusted-vs-untrusted-models">Trusted vs. Untrusted Models</a> for how OrbySystems lets you use a cloud model without necessarily trusting it with your real data.</p><h2 id="trusted-vs-untrusted" tabindex="-1">Trusted vs. untrusted <a class="header-anchor" href="#trusted-vs-untrusted" aria-label="Permalink to &quot;Trusted vs. untrusted&quot;">​</a></h2><p>Only a <strong>trusted</strong> model is given access to your actual project data. An <strong>untrusted</strong> model can still be useful for other tasks, but is never given access to your data. See <a href="/docs/privacy-and-security/trusted-vs-untrusted-models">Trusted vs. Untrusted Models</a> for more on when and why you&#39;d configure one.</p><h2 id="choosing-and-testing-a-model" tabindex="-1">Choosing and testing a model <a class="header-anchor" href="#choosing-and-testing-a-model" aria-label="Permalink to &quot;Choosing and testing a model&quot;">​</a></h2><p>See <a href="/docs/settings/models">Models</a> for how to configure one, and <a href="/docs/tools/model-test">Model Test</a> / <a href="/docs/tools/model-eval-suite">Model Eval Suite</a> for checking that a model works well before relying on it.</p>',13)])])}const y=o(d,[["render",r]]);export{m as __pageData,y as default};
